from lib import *
L = lambda *a, **k: lesson(15, "A0", *a, **k)
A = "adjective"
L(1, "Країни", "Назвати країни й сказати, хто звідки.",
 "Назви країн пишуть з великої літери й без артикля: Germany, France. Винятки, які треба запам'ятати: the USA і the UK. Where is he from? — He's from Spain.",
 [W("country", "/ˈkʌntri/", "noun", "країна", "Ukraine is a big country.", "Україна — велика країна."),
  W("Germany", "/ˈdʒɜːməni/", "noun", "Німеччина", "He's from Germany.", "Він із Німеччини."),
  W("France", "/frɑːns/", "noun", "Франція", "She lives in France.", "Вона живе у Франції."),
  W("Spain", "/speɪn/", "noun", "Іспанія", "They're from Spain.", "Вони з Іспанії."),
  W("Italy", "/ˈɪtəli/", "noun", "Італія", "I love Italy.", "Я обожнюю Італію."),
  W("the USA", "/ðə ˌjuː es ˈeɪ/", "noun", "США", "My uncle lives in the USA.", "Мій дядько живе у США."),
  W("the UK", "/ðə ˌjuː ˈkeɪ/", "noun", "Велика Британія", "London is in the UK.", "Лондон у Великій Британії.")],
 [li("What do you do?", "Повторимо. Ви водій. Що відповісти?", ["I'm a driver.", "I do driver.", "I'm driver."], "I'm a driver."),
  mt([("Germany", "Німеччина"), ("France", "Франція"), ("Spain", "Іспанія"), ("Italy", "Італія")], "Чотири країни Європи."),
  mt([("the USA", "США"), ("the UK", "Велика Британія"), ("Poland", "Польща"), ("country", "країна")], "The USA і the UK — з the."),
  liu("She's from Italy.", "Прослухайте. Звідки вона?", ["З Італії", "З Іспанії", "З Франції"], "Italy — Італія."),
  fb("My cousin lives in ___ USA.", ["the", "a", "an"], "The USA — завжди з the."),
  fb("He's from ___.", ["Germany", "the Germany", "a Germany"], "Germany — без артикля."),
  liu("Where are they from?", "Прослухайте. Що питає людина?", ["Звідки вони", "Де вони", "Хто вони"], "Where … from? — звідки."),
  bs("Звідки він?", ["Where", "is", "he", "from"], ["are", "country"], "Where is he from?"),
  tr("Вони з Іспанії.", ["They're from Spain", "They are from Spain"], "They're from Spain."),
  li("Where is your colleague from?", "Ваша колега з Франції. Що відповісти?", ["She's from France.", "She's from the France.", "She from France is."], "She's from France.")])
L(2, "Я українець", "Назвати свою національність.",
 "Національність — це слово-ознака, перед ним немає a: I'm Ukrainian. Як і країни, національності пишуть з великої літери. Те саме слово часто означає й мову: Polish — «польський» і «польська мова».",
 [W("Ukrainian", "/juːˈkreɪniən/", A, "український; українець, українка", "I'm Ukrainian.", "Я українець."),
  W("Polish", "/ˈpəʊlɪʃ/", A, "польський", "My wife is Polish.", "Моя дружина полька."),
  W("British", "/ˈbrɪtɪʃ/", A, "британський", "He's British.", "Він британець."),
  W("American", "/əˈmerɪkən/", A, "американський", "She's American.", "Вона американка."),
  W("German", "/ˈdʒɜːmən/", A, "німецький", "A German car.", "Німецька машина."),
  W("French", "/frentʃ/", A, "французький", "French wine.", "Французьке вино."),
  W("Spanish", "/ˈspænɪʃ/", A, "іспанський", "Spanish food.", "Іспанська їжа.")],
 [fb("My uncle lives in ___ UK.", ["the", "a", "an"], "The UK.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("Ukraine", "Ukrainian"), ("Poland", "Polish"), ("Germany", "German"), ("France", "French"), ("Spain", "Spanish")], "Кожній країні — свою національність.", "З'єднайте країну й національність"),
  mt([("British", "британський"), ("American", "американський"), ("Ukrainian", "український"), ("Polish", "польський")], "The UK — British, the USA — American."),
  liu("I'm Ukrainian, but I live in Poland.", "Прослухайте. Що каже людина?", ["Українець, живе в Польщі", "Поляк, живе в Україні", "Українець, живе в Україні"], "Ukrainian — українець. Live in Poland — живе в Польщі."),
  mc("Як правильно?", ["I'm Ukrainian.", "I'm a Ukraine.", "I'm from Ukrainian."], "I'm Ukrainian або I'm from Ukraine."),
  fb("He's from the UK. He's ___.", ["British", "American", "the British"], "The UK — British."),
  fb("She's from Germany. She's ___.", ["German", "Germany", "a Germany"], "Germany — German."),
  bs("Моя дружина полька.", ["My", "wife", "is", "Polish"], ["Poland", "a"], "My wife is Polish."),
  tr("Я українець.", ["I'm Ukrainian", "I am Ukrainian"], "I'm Ukrainian — так кажуть і чоловік, і жінка."),
  li("Are you Polish?", "Ви з України. Що відповісти?", ["No, I'm not. I'm Ukrainian.", "No, I don't. I'm Ukraine.", "Yes, I'm Ukrainian."], "No, I'm not. I'm Ukrainian.")])
L(3, "Ви розмовляєте англійською?", "Сказати, якими мовами ви розмовляєте, і попросити говорити повільніше.",
 "I speak… — «я розмовляю…»: I speak Ukrainian and Polish. A little — «трохи»: I speak a little English. Три фрази, які рятують у розмові: I don't understand. Can you speak slowly, please? Can you repeat that, please?",
 [W("speak", "/spiːk/", "verb", "розмовляти", "I speak English.", "Я розмовляю англійською."),
  W("language", "/ˈlæŋɡwɪdʒ/", "noun", "мова", "I speak two languages.", "Я розмовляю двома мовами."),
  W("a little", "/ə ˈlɪtl/", "phrase", "трохи", "I speak a little English.", "Я трохи розмовляю англійською."),
  W("understand", "/ˌʌndəˈstænd/", "verb", "розуміти", "I don't understand.", "Я не розумію."),
  W("slowly", "/ˈsləʊli/", "adverb", "повільно", "Can you speak slowly?", "Можете говорити повільно?"),
  W("repeat", "/rɪˈpiːt/", "verb", "повторити", "Can you repeat that?", "Можете повторити?"),
  W("again", "/əˈɡen/", "adverb", "ще раз", "Again, please.", "Ще раз, будь ласка.")],
 [fb("She's from France. She's ___.", ["French", "France", "a French"], "France — French.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("speak", "розмовляти"), ("understand", "розуміти"), ("repeat", "повторити"), ("language", "мова")], "Слова про мову."),
  mt([("a little", "трохи"), ("slowly", "повільно"), ("again", "ще раз"), ("very well", "дуже добре")], "Як саме ви розмовляєте."),
  liu("Do you speak English?", "Прослухайте. Що вас питають?", ["Чи розмовляєте ви англійською", "Чи ви з Англії", "Чи ви вчите англійську"], "Do you speak…?"),
  liu("Can you speak slowly, please?", "Прослухайте. Про що просить людина?", ["Говорити повільно", "Повторити", "Говорити англійською"], "Slowly — повільно."),
  fb("I speak ___ little English.", ["a", "the", "very"], "A little — трохи."),
  fb("Sorry, I don't ___.", ["understand", "repeat", "language"], "I don't understand — я не розумію."),
  bs("Можете повторити, будь ласка?", ["Can", "you", "repeat", "that", "please"], ["speak", "again"], "Can you repeat that, please?"),
  tr("Я не розумію.", ["I don't understand", "I do not understand"], "I don't understand."),
  li("Do you speak English?", "Ви розмовляєте трохи. Що відповісти?", ["Yes, a little.", "Yes, I am.", "No, I speak English."], "Yes, a little.")])
L(4, "Міста й столиці", "Розповісти про своє місто й назвати столиці.",
 "City — велике місто, town — невелике, village — село. The capital of… — «столиця…»: Kyiv is the capital of Ukraine. Назви міст — без артикля.",
 [W("city", "/ˈsɪti/", "noun", "велике місто", "London is a big city.", "Лондон — велике місто."),
  W("town", "/taʊn/", "noun", "невелике місто", "I live in a small town.", "Я живу в невеликому місті."),
  W("village", "/ˈvɪlɪdʒ/", "noun", "село", "My grandmother lives in a village.", "Моя бабуся живе в селі."),
  W("capital", "/ˈkæpɪtl/", "noun", "столиця", "Kyiv is the capital of Ukraine.", "Київ — столиця України."),
  W("Kyiv", "/ˈkiːɪv/", "noun", "Київ", "I'm from Kyiv.", "Я з Києва."),
  W("Warsaw", "/ˈwɔːsɔː/", "noun", "Варшава", "I live in Warsaw.", "Я живу у Варшаві."),
  W("London", "/ˈlʌndən/", "noun", "Лондон", "London is in the UK.", "Лондон у Великій Британії.")],
 [li("Do you speak Polish?", "Повторимо. Ви розмовляєте трохи. Що відповісти?", ["Yes, a little.", "Yes, I'm Polish little.", "No, I am."], "Yes, a little."),
  mt([("city", "велике місто"), ("town", "невелике місто"), ("village", "село"), ("capital", "столиця")], "Від найбільшого до найменшого: city, town, village."),
  mt([("Kyiv", "Ukraine"), ("Warsaw", "Poland"), ("London", "the UK")], "Столиця й країна.", "З'єднайте столицю й країну"),
  liu("Warsaw is the capital of Poland.", "Прослухайте. Що ви дізналися?", ["Варшава — столиця Польщі", "Варшава — велике місто в Україні", "Варшава біля Польщі"], "The capital of Poland."),
  fb("Kyiv is the capital ___ Ukraine.", ["of", "in", "from"], "The capital of…"),
  fb("I live in a small ___. There are fifty houses.", ["village", "city", "capital"], "П'ятдесят будинків — це село: village."),
  liu("I'm from a small town near Kyiv.", "Прослухайте. Звідки людина?", ["З невеликого міста біля Києва", "З Києва", "Із села біля Києва"], "A small town near Kyiv."),
  bs("Лондон — велике місто.", ["London", "is", "a", "big", "city"], ["the", "town"], "London is a big city."),
  tr("Я живу у Варшаві.", ["I live in Warsaw"], "I live in Warsaw."),
  li("Where do you live?", "Ви живете в невеликому місті в Польщі. Що відповісти?", ["I live in a small town in Poland.", "I'm live small town Poland.", "I live in a small Poland."], "I live in a small town in Poland.")])
L(5, "Що означає це слово?", "Спитати значення слова, як воно пишеться і як сказати щось англійською.",
 "Чотири питання для того, хто вчить мову: What does … mean? — «Що означає …?». How do you say … in English? — «Як сказати … англійською?». How do you spell it? — «Як це пишеться?». Can you write it, please? — «Можете це написати?»",
 [W("mean", "/miːn/", "verb", "означати", "What does it mean?", "Що це означає?"),
  W("word", "/wɜːd/", "noun", "слово", "A new word.", "Нове слово."),
  W("say", "/seɪ/", "verb", "казати", "How do you say it in English?", "Як це сказати англійською?"),
  W("spell", "/spel/", "verb", "називати по літерах", "How do you spell it?", "Як це пишеться?"),
  W("write", "/raɪt/", "verb", "писати", "Can you write it, please?", "Можете це написати?"),
  W("question", "/ˈkwestʃən/", "noun", "питання", "I have a question.", "У мене є питання."),
  W("answer", "/ˈɑːnsə/", "noun", "відповідь", "The right answer.", "Правильна відповідь.")],
 [fb("Kyiv is the ___ of Ukraine.", ["capital", "village", "country"], "The capital.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("mean", "означати"), ("say", "казати"), ("spell", "називати по літерах"), ("write", "писати")], "У write літера w не вимовляється."),
  mt([("word", "слово"), ("question", "питання"), ("answer", "відповідь"), ("language", "мова")], "В answer літера w теж німа."),
  liu("What does this word mean?", "Прослухайте. Що питає людина?", ["Що означає це слово", "Як пишеться це слово", "Чиє це слово"], "Mean — означати."),
  liu("How do you spell your name?", "Прослухайте. Про що вас просять?", ["Назвати ім'я по літерах", "Назвати своє ім'я", "Написати адресу"], "Spell — називати по літерах."),
  fb("How do you ___ «дякую» in English?", ["say", "mean", "answer"], "How do you say … in English?"),
  fb("I have a ___. What does «receipt» mean?", ["question", "answer", "word"], "I have a question."),
  bs("Що це означає?", ["What", "does", "it", "mean"], ["do", "say"], "What does it mean?"),
  tr("Як це пишеться?", ["How do you spell it", "How do you spell that", "How do you spell this"], "How do you spell it?"),
  li("My name is Siobhan.", "Ви не знаєте, як записати це ім'я. Що спитати?", ["How do you spell it?", "What do you do?", "How old is it?"], "How do you spell it?")])
L(6, "Повторення: я у світі", "Розповісти, звідки ви, якими мовами розмовляєте, і не розгубитися, коли чогось не зрозуміли.",
 "Нових слів немає. Повторюємо країни й національності, I speak…, a little, I don't understand, Can you repeat that?, What does it mean?",
 [],
 [li("Where are you from?", "Ви з України, з Києва. Що відповісти?", ["I'm from Kyiv, Ukraine.", "I'm Kyiv from Ukraine.", "I live Ukrainian."], "I'm from Kyiv, Ukraine."),
  fb("She's from Spain. She speaks ___.", ["Spanish", "Spain", "the Spanish"], "Мова — Spanish."),
  tr("Я трохи розмовляю англійською.", ["I speak a little English", "I speak English a little"], "I speak a little English."),
  bs("Можете говорити повільно, будь ласка?", ["Can", "you", "speak", "slowly", "please"], ["repeat", "again"], "Can you speak slowly, please?"),
  liu("I'm Polish, but I live in the UK. I speak Polish and English.", "Прослухайте. Що ви дізналися?", ["Поляк, живе в Британії, знає дві мови", "Британець, живе в Польщі", "Поляк, знає лише польську"], "Polish, the UK, Polish and English."),
  mc("Ви не розчули. Що сказати?", ["Sorry, can you repeat that?", "Sorry, I repeat.", "What do you mean me?"], "Sorry, can you repeat that?"),
  fb("What ___ «village» mean?", ["does", "do", "is"], "What does … mean?"),
  mcu("Яка столиця Польщі?", ["Warsaw", "Kyiv", "London"], "Warsaw is the capital of Poland."),
  tr("Я не розумію.", ["I don't understand", "I do not understand"], "I don't understand."),
  li("How many languages do you speak?", "Ви розмовляєте трьома мовами. Що відповісти?", ["I speak three languages.", "I speak three language.", "I'm three languages."], "I speak three languages.")],
 review=True)
